/* diskprog's table (issue #35): 65,536 words of x' = x * 1103515245 + 12345 from 1, generated by
 * the assembler so the source stays small and the image does not. */
    .section .rodata
    .balign 4
    .globl diskprog_table
diskprog_table:
    .set value, 1
    .rept 65536
    .word value
    .set value, (value * 1103515245 + 12345) & 0xffffffff
    .endr
